-- ============================================================
-- UMKM Smart Advisor — DATA DEMO LOMBA  (Warung Bu Siti)
-- Akun  : siti@warungbusiti.com
-- ============================================================
-- Cara menjalankan (SALIN & JALANKAN di Supabase SQL Editor):
--
--  1. Pastikan sudah register akun:  siti@warungbusiti.com
--     (password Demo: WarungSiti2024!)
--  2. Jalankan schema.sql DAN data.sql lebih dulu (sekali saja).
--  3. Jalankan file ini (seed-dummy.sql).
--     - Bisnis "Warung Bu Siti" otomatis dibuat jika belum ada,
--       atau diperbarui jika sudah ada (TIDAK membuat duplikat).
--     - Semua produk/transaksi/notifikasi menempel ke bisnis milik
--       akun siti@warungbusiti.com (dicari otomatis via email).
--  4. Login ulang di /login lalu lihat dashboard terisi data.
--
-- File ini IDEMPOTENT: aman dijalankan berulang kali
-- (semua row pakai UUID tetap + ON CONFLICT DO NOTHING).
-- ============================================================

-- ============================================================
-- 0. PASTIKAN PROFIL & BISNIS ADA (tanpa membuat duplikat)
-- ============================================================
DO $$
DECLARE
  v_user_id uuid;
  v_biz_id  uuid;
BEGIN
  SELECT id INTO v_user_id FROM auth.users
  WHERE email = 'siti@warungbusiti.com' LIMIT 1;

  IF v_user_id IS NULL THEN
    RAISE NOTICE 'Akun siti@warungbusiti.com belum ada. Register dulu lewat /register.';
    RETURN;
  END IF;

  SELECT id INTO v_biz_id FROM businesses
  WHERE created_by = v_user_id
  ORDER BY created_at ASC LIMIT 1;

  IF v_biz_id IS NULL THEN
    INSERT INTO businesses (id, created_by, name, type, address, phone, email)
    VALUES ('d1000000-0000-0000-0000-000000000001'::uuid, v_user_id,
            'Warung Bu Siti', 'Rumah Makan',
            'Jl. Melati No. 12, Bandung', '0812-3456-7890', 'warungbusiti@gmail.com');
    v_biz_id := 'd1000000-0000-0000-0000-000000000001'::uuid;
  ELSE
    UPDATE businesses SET
      name = 'Warung Bu Siti',
      type = 'Rumah Makan',
      address = 'Jl. Melati No. 12, Bandung',
      phone  = '0812-3456-7890',
      email  = 'warungbusiti@gmail.com',
      updated_at = now()
    WHERE id = v_biz_id;
  END IF;

  UPDATE profiles SET
    full_name = 'Siti Rahayu',
    phone  = '0812-3456-7890',
    address = 'Jl. Melati No. 12, Bandung',
    updated_at = now()
  WHERE id = v_user_id
    AND (full_name IS DISTINCT FROM 'Siti Rahayu'
      OR phone     IS DISTINCT FROM '0812-3456-7890'
      OR address   IS DISTINCT FROM 'Jl. Melati No. 12, Bandung');
END $$;

-- ============================================================
-- 1. KATEGORI PRODUK (tambah yg relevan warung; tanpa duplikat)
-- ============================================================
INSERT INTO product_categories (id, name) VALUES
  ('a1000000-0000-0000-0000-000000000011'::uuid, 'Camilan'),
  ('a1000000-0000-0000-0000-000000000012'::uuid, 'Sembako & Bahan Pokok'),
  ('a1000000-0000-0000-0000-000000000013'::uuid, 'Bumbu & Rempah')
ON CONFLICT (name) DO NOTHING;

-- ============================================================
-- 2. PRODUK (stock di sini = stok AWAL / hasil restock;
--    nilai stok akhir dihitung ulang di langkah 7)
-- ============================================================
INSERT INTO products (id, business_id, category_id, name, price, stock, min_stock)
SELECT p.id::uuid,
       (SELECT b.id FROM businesses b
        JOIN auth.users u ON u.id = b.created_by
        WHERE u.email = 'siti@warungbusiti.com'
        ORDER BY b.created_at LIMIT 1),
       pc.id,
       p.name, p.price, p.base, p.min_stock
FROM (VALUES
  ('e1000000-0000-0000-0000-000000000001', 'Makanan', 'Nasi Padang', 25000, 20, 5),
  ('e1000000-0000-0000-0000-000000000002', 'Makanan', 'Nasi Goreng Spesial', 22000, 30, 5),
  ('e1000000-0000-0000-0000-000000000003', 'Makanan', 'Ayam Geprek', 18000, 24, 5),
  ('e1000000-0000-0000-0000-000000000004', 'Makanan', 'Mie Ayam', 17000, 21, 5),
  ('e1000000-0000-0000-0000-000000000005', 'Makanan', 'Sate Ayam (10 tusuk)', 20000, 29, 5),
  ('e1000000-0000-0000-0000-000000000006', 'Minuman', 'Es Teh Manis', 5000, 24, 10),
  ('e1000000-0000-0000-0000-000000000007', 'Minuman', 'Es Jeruk', 6000, 19, 10),
  ('e1000000-0000-0000-0000-000000000008', 'Minuman', 'Kopi Susu Gula Aren', 15000, 30, 10),
  ('e1000000-0000-0000-0000-000000000009', 'Minuman', 'Es Campur', 12000, 27, 8),
  ('e1000000-0000-0000-0000-000000000010', 'Camilan', 'Keripik Singkong', 10000, 7, 5),
  ('e1000000-0000-0000-0000-000000000011', 'Camilan', 'Tahu & Tempe Goreng', 5000, 30, 8),
  ('e1000000-0000-0000-0000-000000000012', 'Camilan', 'Roti Bakar', 12000, 4, 5),
  ('e1000000-0000-0000-0000-000000000013', 'Sembako & Bahan Pokok', 'Beras Premium 5kg', 65000, 11, 10),
  ('e1000000-0000-0000-0000-000000000014', 'Sembako & Bahan Pokok', 'Minyak Goreng 1L', 16000, 38, 12),
  ('e1000000-0000-0000-0000-000000000015', 'Sembako & Bahan Pokok', 'Telur Ayam (1kg)', 26000, 12, 10),
  ('e1000000-0000-0000-0000-000000000016', 'Sembako & Bahan Pokok', 'Gula Pasir 1kg', 15000, 20, 10),
  ('e1000000-0000-0000-0000-000000000017', 'Bumbu & Rempah', 'Kecap Manis 600ml', 18000, 28, 6),
  ('e1000000-0000-0000-0000-000000000018', 'Bumbu & Rempah', 'Bumbu Masak Instan', 2500, 13, 10)
) AS p(id, category_name, name, price, base, min_stock)
JOIN product_categories pc ON pc.name = p.category_name
ON CONFLICT (id) DO NOTHING;

