-- ============================================================
-- 7. SINKRONKAN STOK AKHIR
--    stok = restock_awal - SEMUA terjual (Selesai+Pending+Batal)
--           + retur(Batal) - kerugian(adjustment negatif)
-- ============================================================
UPDATE products p
SET stock = v.base
          - COALESCE(s.sold, 0)
          + COALESCE(b.retur, 0)
          - COALESCE(a.loss, 0)
FROM (VALUES
  ('e1000000-0000-0000-0000-000000000001'::uuid, 20),
  ('e1000000-0000-0000-0000-000000000002'::uuid, 30),
  ('e1000000-0000-0000-0000-000000000003'::uuid, 24),
  ('e1000000-0000-0000-0000-000000000004'::uuid, 21),
  ('e1000000-0000-0000-0000-000000000005'::uuid, 29),
  ('e1000000-0000-0000-0000-000000000006'::uuid, 24),
  ('e1000000-0000-0000-0000-000000000007'::uuid, 19),
  ('e1000000-0000-0000-0000-000000000008'::uuid, 30),
  ('e1000000-0000-0000-0000-000000000009'::uuid, 27),
  ('e1000000-0000-0000-0000-000000000010'::uuid, 7),
  ('e1000000-0000-0000-0000-000000000011'::uuid, 30),
  ('e1000000-0000-0000-0000-000000000012'::uuid, 4),
  ('e1000000-0000-0000-0000-000000000013'::uuid, 11),
  ('e1000000-0000-0000-0000-000000000014'::uuid, 38),
  ('e1000000-0000-0000-0000-000000000015'::uuid, 12),
  ('e1000000-0000-0000-0000-000000000016'::uuid, 20),
  ('e1000000-0000-0000-0000-000000000017'::uuid, 28),
  ('e1000000-0000-0000-0000-000000000018'::uuid, 13)
) AS v(id, base)
LEFT JOIN (
  SELECT ti.product_id, SUM(ti.quantity) AS sold
  FROM transaction_items ti
  JOIN transactions tr ON tr.id = ti.transaction_id
  WHERE tr.id::text LIKE 'f1000000-%'
  GROUP BY ti.product_id
) s ON s.product_id = v.id
LEFT JOIN (
  SELECT ti.product_id, SUM(ti.quantity) AS retur
  FROM transaction_items ti
  JOIN transactions tr ON tr.id = ti.transaction_id
  WHERE tr.id::text LIKE 'f1000000-%'
    AND tr.status = 'Batal'
  GROUP BY ti.product_id
) b ON b.product_id = v.id
LEFT JOIN (VALUES
  ('e1000000-0000-0000-0000-000000000010'::uuid, 2),
  ('e1000000-0000-0000-0000-000000000013'::uuid, 1),
  ('e1000000-0000-0000-0000-000000000018'::uuid, 5)
) AS a(product_id, loss) ON a.product_id = v.id
WHERE p.id = v.id;

-- ============================================================
-- 8. NOTIFIKASI (beragam kategori/prioritas, sebagian dibaca)
-- ============================================================
INSERT INTO notifications (id, business_id, user_id, title, description, category, priority, is_read, created_at)
SELECT n.id::uuid,
       (SELECT b.id FROM businesses b
        JOIN auth.users u ON u.id = b.created_by
        WHERE u.email = 'siti@warungbusiti.com'
        ORDER BY b.created_at LIMIT 1),
       (SELECT id FROM auth.users WHERE email = 'siti@warungbusiti.com'),
       n.title, n.description,
       n.category::notification_category,
       n.priority::notification_priority,
       n.is_read,
       (now()::date - make_interval(days => n.age_days, hours => n.hour, mins => n.min_rt))
FROM (VALUES
  ('f4000000-0000-0000-0000-000000000001', 'Stok hampir habis: Roti Bakar', 'Stok Roti Bakar mencapai 0. Segera lakukan restock.', 'inventory', 'high', true, 0, 9, 0),
